import{_ as o}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as t}from"./chunks/财务首页.BShnXpzp.js";import{_ as d,o as a,c as r,a2 as c}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.DQD-VKbT.png",i="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.ClvQZ23V.png",l="/newx-doc/assets/%E7%AC%AC%E4%BA%8C%E6%AD%A5-01.Dy2XzDeB.png",v=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"fms/build.md","filePath":"fms/build.md","lastUpdated":null}'),m={name:"fms/build.md"};function n(_,e,p,u,f,h){return a(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p>进度说明：</p><ul><li>管理后台，请使用 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-ui-admin-vue3</a> 仓库的 <code>master</code> 分支</li><li>后端项目，请使用 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/ruoyi-vue-pro</a> 仓库的 <code>master</code>（JDK8）、<code>master-jdk17</code>（JDK17/21）或 <code>master-jdk25</code>（JDK25）分支</li></ul><p>FMS 系统，后端由 <code>yudao-module-fms</code> 模块实现，前端由 <code>yudao-ui-admin-vue3</code> 的 <code>fms</code> 目录实现。</p><p>考虑到编译速度，默认 <code>yudao-module-fms</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-fms</code> 模块</li><li>第二步，导入 FMS 系统的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li></ul><h2 id="_1-第一步-开启模块" tabindex="-1">1. 第一步，开启模块 <a class="header-anchor" href="#_1-第一步-开启模块" aria-label="Permalink to &quot;1. 第一步，开启模块&quot;">​</a></h2><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-fms</code> 模块的注释。如下图所示：</p><p><img src="'+s+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-fms</code> 模块。如下图所示：</p><p><img src="'+i+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+o+'" alt="刷新 Maven 依赖"></p><h2 id="_2-第二步-导入-sql" tabindex="-1">2. 第二步，导入 SQL <a class="header-anchor" href="#_2-第二步-导入-sql" aria-label="Permalink to &quot;2. 第二步，导入 SQL&quot;">​</a></h2><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/fms.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。如下图所示：</p><p>友情提示：↑↑↑ fms.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><p><img src="'+l+'" alt="导入数据库"></p><p>以 <code>fms_</code> 作为前缀的表，就是 FMS 模块的表，一共 <strong>30</strong> 张，按业务模块分为：</p><table tabindex="0"><thead><tr><th>子前缀</th><th>模块</th><th>表数量</th></tr></thead><tbody><tr><td><code>fms_account_*</code>、<code>fms_finance_*</code>、<code>fms_currency</code>、<code>fms_subject*</code>、<code>fms_auxiliary_*</code>、<code>fms_assist_combination</code>、<code>fms_initial_balance</code>、<code>fms_voucher_word</code>、<code>fms_digest</code>、<code>fms_voucher_template*</code></td><td>设置管理</td><td>15</td></tr><tr><td><code>fms_voucher</code>、<code>fms_voucher_entry</code></td><td>凭证管理</td><td>2</td></tr><tr><td>—</td><td>账簿管理</td><td>0</td></tr><tr><td><code>fms_report_template</code>、<code>fms_balance_sheet_*</code>、<code>fms_income_statement_*</code>、<code>fms_cash_flow_*</code></td><td>报表管理</td><td>9</td></tr><tr><td><code>fms_closing*</code></td><td>结账管理</td><td>4</td></tr></tbody></table><h2 id="_3-第三步-重启项目" tabindex="-1">3. 第三步，重启项目 <a class="header-anchor" href="#_3-第三步-重启项目" aria-label="Permalink to &quot;3. 第三步，重启项目&quot;">​</a></h2><p>重启后端项目，然后访问前端的 FMS 菜单，确认功能是否生效。如下图所示：</p><p><img src="'+t+'" alt="确认功能是否生效"></p><p>至此，我们就成功开启了 FMS 的功能 🙂</p>',24)])])}const A=d(m,[["render",n]]);export{v as __pageData,A as default};
